// Generated by scripts/generate-articles.ts. Do not edit.
export default {"html":"<p data-line=\"0\" class=\"code-line\">Do you write elements like this in Ionic Angular templates?</p>\n<div class=\"code-block-container\"><pre class=\"shiki github-dark\" style=\"background-color:#151e2c;color:#e1e4e8\"><code class=\"code-line\" data-line=\"2\"><span class=\"line\"><span style=\"color:#E1E4E8\">&lt;</span><span style=\"color:#85E89D\">ion-item</span><span style=\"color:#B392F0\"> button</span><span style=\"color:#E1E4E8\">=</span><span style=\"color:#9ECBFF\">\"true\"</span><span style=\"color:#E1E4E8\">&gt;&lt;/</span><span style=\"color:#85E89D\">ion-item</span><span style=\"color:#E1E4E8\">&gt;</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">&lt;</span><span style=\"color:#85E89D\">ion-progress-bar</span><span style=\"color:#B392F0\"> value</span><span style=\"color:#E1E4E8\">=</span><span style=\"color:#9ECBFF\">\"50\"</span><span style=\"color:#E1E4E8\">&gt;&lt;/</span><span style=\"color:#85E89D\">ion-progress-bar</span><span style=\"color:#E1E4E8\">&gt;</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">&lt;</span><span style=\"color:#85E89D\">ion-radio</span><span style=\"color:#B392F0\"> labelPlacement</span><span style=\"color:#E1E4E8\">=</span><span style=\"color:#9ECBFF\">\"center\"</span><span style=\"color:#E1E4E8\">&gt;&lt;/</span><span style=\"color:#85E89D\">ion-radio</span><span style=\"color:#E1E4E8\">&gt;</span></span>\n<span class=\"line\"></span></code></pre></div><p data-line=\"8\" class=\"code-line\">This code looks correct at a glance, but TypeScript's type information actually reports errors. Many Ionic component attributes expect boolean, number, or specific string literal types—not plain strings.</p>\n<h2 id=\"html-vs.-js-frameworks\" data-line=\"10\" class=\"code-line\"><a class=\"header-anchor-link\" href=\"#html-vs.-js-frameworks\" aria-hidden=\"true\"></a> HTML vs. JS frameworks</h2>\n<p data-line=\"12\" class=\"code-line\">In plain HTML, every attribute value is treated as a string. The same applies to Ionic components—for example:</p>\n<div class=\"code-block-container\"><pre class=\"shiki github-dark\" style=\"background-color:#151e2c;color:#e1e4e8\"><code class=\"code-line\" data-line=\"14\"><span class=\"line\"><span style=\"color:#a0aab5\">&lt;!-- Ionic component: processed as a string --&gt;</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">&lt;</span><span style=\"color:#85E89D\">ion-item</span><span style=\"color:#B392F0\"> button</span><span style=\"color:#E1E4E8\">=</span><span style=\"color:#9ECBFF\">\"true\"</span><span style=\"color:#B392F0\"> disabled</span><span style=\"color:#E1E4E8\">=</span><span style=\"color:#9ECBFF\">\"false\"</span><span style=\"color:#E1E4E8\">&gt;</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">&lt;</span><span style=\"color:#85E89D\">ion-progress-bar</span><span style=\"color:#B392F0\"> value</span><span style=\"color:#E1E4E8\">=</span><span style=\"color:#9ECBFF\">\"50\"</span><span style=\"color:#E1E4E8\">&gt;</span></span>\n<span class=\"line\"></span></code></pre></div><p data-line=\"20\" class=\"code-line\">Here, the Ionic Framework receives the string <code>\"true\"</code> for <code>button=\"true\"</code> and converts it internally to the appropriate type (boolean).</p>\n<p data-line=\"22\" class=\"code-line\">With Angular, however, <code>components.d.ts</code> defines strict types for each component's attributes:</p>\n<div class=\"code-block-container\"><pre class=\"shiki github-dark\" style=\"background-color:#151e2c;color:#e1e4e8\"><code class=\"code-line\" data-line=\"24\"><span class=\"line\"><span style=\"color:#a0aab5\">// Example from @ionic/core/dist/types/components.d.ts</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">interface</span><span style=\"color:#B392F0\"> IonItem</span><span style=\"color:#E1E4E8\"> {</span></span>\n<span class=\"line\"><span style=\"color:#FFAB70\">  button</span><span style=\"color:#F97583\">?:</span><span style=\"color:#79B8FF\"> boolean</span><span style=\"color:#E1E4E8\">;  </span><span style=\"color:#a0aab5\">// Expects a boolean</span></span>\n<span class=\"line\"><span style=\"color:#FFAB70\">  disabled</span><span style=\"color:#F97583\">?:</span><span style=\"color:#79B8FF\"> boolean</span><span style=\"color:#E1E4E8\">;</span></span>\n<span class=\"line\"><span style=\"color:#FFAB70\">  lines</span><span style=\"color:#F97583\">?:</span><span style=\"color:#9ECBFF\"> 'full'</span><span style=\"color:#F97583\"> |</span><span style=\"color:#9ECBFF\"> 'inset'</span><span style=\"color:#F97583\"> |</span><span style=\"color:#9ECBFF\"> 'none'</span><span style=\"color:#E1E4E8\">;  </span><span style=\"color:#a0aab5\">// Expects specific string literal types</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">}</span></span>\n<span class=\"line\"></span></code></pre></div><p data-line=\"33\" class=\"code-line\">TypeScript type-checks against these definitions, which leads to problems like:</p>\n<div class=\"code-block-container\"><pre class=\"shiki github-dark\" style=\"background-color:#151e2c;color:#e1e4e8\"><code class=\"code-line\" data-line=\"35\"><span class=\"line\"><span style=\"color:#a0aab5\">&lt;!-- TypeScript type checking reports an error --&gt;</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">&lt;</span><span style=\"color:#85E89D\">ion-item</span><span style=\"color:#B392F0\"> button</span><span style=\"color:#E1E4E8\">=</span><span style=\"color:#9ECBFF\">\"true\"</span><span style=\"color:#E1E4E8\">&gt;  </span><span style=\"color:#a0aab5\">&lt;!-- string \"true\" ≠ boolean true --&gt;</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">&lt;</span><span style=\"color:#85E89D\">ion-item</span><span style=\"color:#B392F0\"> lines</span><span style=\"color:#E1E4E8\">=</span><span style=\"color:#9ECBFF\">\"invalid\"</span><span style=\"color:#E1E4E8\">&gt;  </span><span style=\"color:#a0aab5\">&lt;!-- \"invalid\" is not an allowed value --&gt;</span></span>\n<span class=\"line\"></span></code></pre></div><p data-line=\"41\" class=\"code-line\">Recent WebStorm versions now surface these type-check errors:</p>\n<p data-line=\"43\" class=\"code-line\"><img src=\"/images/7d39ddfe9c7cf1/ts-check-error.png\" alt=\"\" class=\"md-img\" loading=\"lazy\"></p>\n<p data-line=\"46\" class=\"code-line\">This TypeScript checking targets built Ionic components, so it does not block the Angular build. Still, seeing type errors pushes developers to learn the correct way to write code.<br>\nSo I built an ESLint rule to detect this problem early and auto-fix it.</p>\n<h2 id=\"one-shot-fix-with-an-eslint-rule\" data-line=\"50\" class=\"code-line\"><a class=\"header-anchor-link\" href=\"#one-shot-fix-with-an-eslint-rule\" aria-hidden=\"true\"></a> One-shot fix with an ESLint rule</h2>\n<p data-line=\"52\" class=\"code-line\">I developed the <code>@rdlabo/rules/ionic-attr-type-check</code> ESLint rule to address this at the root. \"Does not block the build\" also means you cannot get a list of errors in one place—you had to eyeball errors and fixes in the IDE, which was not practical.</p>\n<h2 id=\"main-features\" data-line=\"54\" class=\"code-line\"><a class=\"header-anchor-link\" href=\"#main-features\" aria-hidden=\"true\"></a> Main features</h2>\n<h3 id=\"1.-automatic-type-detection\" data-line=\"56\" class=\"code-line\"><a class=\"header-anchor-link\" href=\"#1.-automatic-type-detection\" aria-hidden=\"true\"></a> 1. Automatic type detection</h3>\n<p data-line=\"58\" class=\"code-line\">At runtime the rule loads <code>@ionic/core/dist/types/components.d.ts</code> and dynamically parses attribute types for each Ionic component. That gives you:</p>\n<ul data-line=\"60\" class=\"code-line\">\n<li data-line=\"60\" class=\"code-line\">Coverage for all Ionic components: <code>ion-item</code>, <code>ion-button</code>, <code>ion-modal</code>, and the rest</li>\n<li data-line=\"61\" class=\"code-line\">Automatic type classification: boolean, number, and string literal unions</li>\n<li data-line=\"62\" class=\"code-line\">Future Ionic versions: loading from the type definition file means new components and attributes are picked up automatically</li>\n</ul>\n<h3 id=\"2.-validation-and-fix-support\" data-line=\"64\" class=\"code-line\"><a class=\"header-anchor-link\" href=\"#2.-validation-and-fix-support\" aria-hidden=\"true\"></a> 2. Validation and fix support</h3>\n<p data-line=\"66\" class=\"code-line\">The rule validates the following types and reports errors:</p>\n<h4 id=\"boolean-attributes\" data-line=\"68\" class=\"code-line\"><a class=\"header-anchor-link\" href=\"#boolean-attributes\" aria-hidden=\"true\"></a> Boolean attributes</h4>\n<div class=\"code-block-container\"><pre class=\"shiki github-dark\" style=\"background-color:#151e2c;color:#e1e4e8\"><code class=\"code-line\" data-line=\"69\"><span class=\"line\"><span style=\"color:#a0aab5\">&lt;!-- ❌ Before --&gt;</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">&lt;</span><span style=\"color:#85E89D\">ion-item</span><span style=\"color:#B392F0\"> button</span><span style=\"color:#E1E4E8\">=</span><span style=\"color:#9ECBFF\">\"true\"</span><span style=\"color:#B392F0\"> disabled</span><span style=\"color:#E1E4E8\">=</span><span style=\"color:#9ECBFF\">\"false\"</span><span style=\"color:#E1E4E8\">&gt;&lt;/</span><span style=\"color:#85E89D\">ion-item</span><span style=\"color:#E1E4E8\">&gt;</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">&lt;</span><span style=\"color:#85E89D\">ion-toggle</span><span style=\"color:#B392F0\"> checked</span><span style=\"color:#E1E4E8\">=</span><span style=\"color:#9ECBFF\">\"true\"</span><span style=\"color:#E1E4E8\">&gt;&lt;/</span><span style=\"color:#85E89D\">ion-toggle</span><span style=\"color:#E1E4E8\">&gt;</span></span>\n<span class=\"line\"></span>\n<span class=\"line\"><span style=\"color:#a0aab5\">&lt;!-- ✅ After --&gt;</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">&lt;</span><span style=\"color:#85E89D\">ion-item</span><span style=\"color:#B392F0\"> [button]</span><span style=\"color:#E1E4E8\">=</span><span style=\"color:#9ECBFF\">\"true\"</span><span style=\"color:#B392F0\"> [disabled]</span><span style=\"color:#E1E4E8\">=</span><span style=\"color:#9ECBFF\">\"false\"</span><span style=\"color:#E1E4E8\">&gt;&lt;/</span><span style=\"color:#85E89D\">ion-item</span><span style=\"color:#E1E4E8\">&gt;</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">&lt;</span><span style=\"color:#85E89D\">ion-toggle</span><span style=\"color:#B392F0\"> [checked]</span><span style=\"color:#E1E4E8\">=</span><span style=\"color:#9ECBFF\">\"true\"</span><span style=\"color:#E1E4E8\">&gt;&lt;/</span><span style=\"color:#85E89D\">ion-toggle</span><span style=\"color:#E1E4E8\">&gt;</span></span>\n<span class=\"line\"></span></code></pre></div><h4 id=\"number-attributes\" data-line=\"79\" class=\"code-line\"><a class=\"header-anchor-link\" href=\"#number-attributes\" aria-hidden=\"true\"></a> Number attributes</h4>\n<div class=\"code-block-container\"><pre class=\"shiki github-dark\" style=\"background-color:#151e2c;color:#e1e4e8\"><code class=\"code-line\" data-line=\"80\"><span class=\"line\"><span style=\"color:#a0aab5\">&lt;!-- ❌ Before --&gt;</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">&lt;</span><span style=\"color:#85E89D\">ion-progress-bar</span><span style=\"color:#B392F0\"> value</span><span style=\"color:#E1E4E8\">=</span><span style=\"color:#9ECBFF\">\"50\"</span><span style=\"color:#B392F0\"> buffer</span><span style=\"color:#E1E4E8\">=</span><span style=\"color:#9ECBFF\">\"75\"</span><span style=\"color:#E1E4E8\">&gt;&lt;/</span><span style=\"color:#85E89D\">ion-progress-bar</span><span style=\"color:#E1E4E8\">&gt;</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">&lt;</span><span style=\"color:#85E89D\">ion-range</span><span style=\"color:#B392F0\"> min</span><span style=\"color:#E1E4E8\">=</span><span style=\"color:#9ECBFF\">\"0\"</span><span style=\"color:#B392F0\"> max</span><span style=\"color:#E1E4E8\">=</span><span style=\"color:#9ECBFF\">\"100\"</span><span style=\"color:#E1E4E8\">&gt;&lt;/</span><span style=\"color:#85E89D\">ion-range</span><span style=\"color:#E1E4E8\">&gt;</span></span>\n<span class=\"line\"></span>\n<span class=\"line\"><span style=\"color:#a0aab5\">&lt;!-- ✅ After --&gt;</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">&lt;</span><span style=\"color:#85E89D\">ion-progress-bar</span><span style=\"color:#B392F0\"> [value]</span><span style=\"color:#E1E4E8\">=</span><span style=\"color:#9ECBFF\">\"50\"</span><span style=\"color:#B392F0\"> [buffer]</span><span style=\"color:#E1E4E8\">=</span><span style=\"color:#9ECBFF\">\"75\"</span><span style=\"color:#E1E4E8\">&gt;&lt;/</span><span style=\"color:#85E89D\">ion-progress-bar</span><span style=\"color:#E1E4E8\">&gt;</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">&lt;</span><span style=\"color:#85E89D\">ion-range</span><span style=\"color:#B392F0\"> [min]</span><span style=\"color:#E1E4E8\">=</span><span style=\"color:#9ECBFF\">\"0\"</span><span style=\"color:#B392F0\"> [max]</span><span style=\"color:#E1E4E8\">=</span><span style=\"color:#9ECBFF\">\"100\"</span><span style=\"color:#E1E4E8\">&gt;&lt;/</span><span style=\"color:#85E89D\">ion-range</span><span style=\"color:#E1E4E8\">&gt;</span></span>\n<span class=\"line\"></span></code></pre></div><h4 id=\"string-literal-union-attributes\" data-line=\"90\" class=\"code-line\"><a class=\"header-anchor-link\" href=\"#string-literal-union-attributes\" aria-hidden=\"true\"></a> String literal union attributes</h4>\n<div class=\"code-block-container\"><pre class=\"shiki github-dark\" style=\"background-color:#151e2c;color:#e1e4e8\"><code class=\"code-line\" data-line=\"91\"><span class=\"line\"><span style=\"color:#a0aab5\">&lt;!-- ❌ An error is displayed --&gt;</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">&lt;</span><span style=\"color:#85E89D\">ion-item</span><span style=\"color:#B392F0\"> lines</span><span style=\"color:#E1E4E8\">=</span><span style=\"color:#9ECBFF\">\"invalid\"</span><span style=\"color:#E1E4E8\">&gt;&lt;/</span><span style=\"color:#85E89D\">ion-item</span><span style=\"color:#E1E4E8\">&gt;</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">&lt;</span><span style=\"color:#85E89D\">ion-radio</span><span style=\"color:#B392F0\"> labelPlacement</span><span style=\"color:#E1E4E8\">=</span><span style=\"color:#9ECBFF\">\"center\"</span><span style=\"color:#E1E4E8\">&gt;&lt;/</span><span style=\"color:#85E89D\">ion-radio</span><span style=\"color:#E1E4E8\">&gt;</span></span>\n<span class=\"line\"></span>\n<span class=\"line\"><span style=\"color:#a0aab5\">&lt;!-- ✅ Correct value --&gt;</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">&lt;</span><span style=\"color:#85E89D\">ion-item</span><span style=\"color:#B392F0\"> lines</span><span style=\"color:#E1E4E8\">=</span><span style=\"color:#9ECBFF\">\"full\"</span><span style=\"color:#E1E4E8\">&gt;&lt;/</span><span style=\"color:#85E89D\">ion-item</span><span style=\"color:#E1E4E8\">&gt;</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">&lt;</span><span style=\"color:#85E89D\">ion-radio</span><span style=\"color:#B392F0\"> labelPlacement</span><span style=\"color:#E1E4E8\">=</span><span style=\"color:#9ECBFF\">\"start\"</span><span style=\"color:#E1E4E8\">&gt;&lt;/</span><span style=\"color:#85E89D\">ion-radio</span><span style=\"color:#E1E4E8\">&gt;</span></span>\n<span class=\"line\"></span></code></pre></div><h3 id=\"3.-auto-fix\" data-line=\"101\" class=\"code-line\"><a class=\"header-anchor-link\" href=\"#3.-auto-fix\" aria-hidden=\"true\"></a> 3. Auto-fix</h3>\n<p data-line=\"103\" class=\"code-line\">The current version supports auto-fix for boolean and number attributes:</p>\n<div class=\"code-block-container\"><pre class=\"shiki github-dark\" style=\"background-color:#151e2c;color:#e1e4e8\"><code class=\"code-line\" data-line=\"105\"><span class=\"line\"><span style=\"color:#B392F0\">npx</span><span style=\"color:#9ECBFF\"> eslint</span><span style=\"color:#79B8FF\"> --fix</span><span style=\"color:#9ECBFF\"> src/</span><span style=\"color:#79B8FF\">**</span><span style=\"color:#9ECBFF\">/</span><span style=\"color:#79B8FF\">*</span><span style=\"color:#9ECBFF\">.html</span></span>\n<span class=\"line\"></span></code></pre></div><p data-line=\"109\" class=\"code-line\">String literal union attributes are detection-only for now.</p>\n<h2 id=\"usage\" data-line=\"112\" class=\"code-line\"><a class=\"header-anchor-link\" href=\"#usage\" aria-hidden=\"true\"></a> Usage</h2>\n<h2 id=\"installation\" data-line=\"114\" class=\"code-line\"><a class=\"header-anchor-link\" href=\"#installation\" aria-hidden=\"true\"></a> Installation</h2>\n<div class=\"code-block-container\"><pre class=\"shiki github-dark\" style=\"background-color:#151e2c;color:#e1e4e8\"><code class=\"code-line\" data-line=\"116\"><span class=\"line\"><span style=\"color:#B392F0\">npm</span><span style=\"color:#9ECBFF\"> install</span><span style=\"color:#9ECBFF\"> @rdlabo/eslint-plugin-rules</span><span style=\"color:#79B8FF\"> --save-dev</span></span>\n<span class=\"line\"></span></code></pre></div><h2 id=\"configuration\" data-line=\"120\" class=\"code-line\"><a class=\"header-anchor-link\" href=\"#configuration\" aria-hidden=\"true\"></a> Configuration</h2>\n<p data-line=\"122\" class=\"code-line\">Add the following to your ESLint config (<code>eslint.config.js</code>):</p>\n<div class=\"code-block-container\"><pre class=\"shiki github-dark\" style=\"background-color:#151e2c;color:#e1e4e8\"><code class=\"code-line\" data-line=\"124\"><span class=\"line\"><span style=\"color:#F97583\">import</span><span style=\"color:#E1E4E8\"> rdlabo </span><span style=\"color:#F97583\">from</span><span style=\"color:#9ECBFF\"> '@rdlabo/eslint-plugin-rules'</span><span style=\"color:#E1E4E8\">;</span></span>\n<span class=\"line\"></span>\n<span class=\"line\"><span style=\"color:#F97583\">export</span><span style=\"color:#F97583\"> default</span><span style=\"color:#E1E4E8\"> [</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  {</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">    files: [</span><span style=\"color:#9ECBFF\">'*.html'</span><span style=\"color:#E1E4E8\">],</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">    plugins: {</span></span>\n<span class=\"line\"><span style=\"color:#9ECBFF\">      '@rdlabo/rules'</span><span style=\"color:#E1E4E8\">: rdlabo,</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">    },</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">    rules: {</span></span>\n<span class=\"line\"><span style=\"color:#9ECBFF\">      '@rdlabo/rules/ionic-attr-type-check'</span><span style=\"color:#E1E4E8\">: </span><span style=\"color:#9ECBFF\">'error'</span><span style=\"color:#E1E4E8\">,</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">    },</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  }</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">];</span></span>\n<span class=\"line\"></span></code></pre></div><p data-line=\"140\" class=\"code-line\">That enables attribute type checking for Ionic components in HTML template files.</p>\n<h2 id=\"example-in-practice\" data-line=\"142\" class=\"code-line\"><a class=\"header-anchor-link\" href=\"#example-in-practice\" aria-hidden=\"true\"></a> Example in practice</h2>\n<p data-line=\"144\" class=\"code-line\">If you write code like this during development:</p>\n<div class=\"code-block-container\"><pre class=\"shiki github-dark\" style=\"background-color:#151e2c;color:#e1e4e8\"><code class=\"code-line\" data-line=\"146\"><span class=\"line\"><span style=\"color:#E1E4E8\">&lt;</span><span style=\"color:#85E89D\">ion-item</span><span style=\"color:#B392F0\"> button</span><span style=\"color:#E1E4E8\">=</span><span style=\"color:#9ECBFF\">\"true\"</span><span style=\"color:#B392F0\"> lines</span><span style=\"color:#E1E4E8\">=</span><span style=\"color:#9ECBFF\">\"true\"</span><span style=\"color:#E1E4E8\">&gt;</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  &lt;</span><span style=\"color:#85E89D\">ion-label</span><span style=\"color:#E1E4E8\">&gt;Settings&lt;/</span><span style=\"color:#85E89D\">ion-label</span><span style=\"color:#E1E4E8\">&gt;</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">&lt;/</span><span style=\"color:#85E89D\">ion-item</span><span style=\"color:#E1E4E8\">&gt;</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">&lt;</span><span style=\"color:#85E89D\">ion-progress-bar</span><span style=\"color:#B392F0\"> value</span><span style=\"color:#E1E4E8\">=</span><span style=\"color:#9ECBFF\">\"50\"</span><span style=\"color:#E1E4E8\">&gt;&lt;/</span><span style=\"color:#85E89D\">ion-progress-bar</span><span style=\"color:#E1E4E8\">&gt;</span></span>\n<span class=\"line\"></span></code></pre></div><p data-line=\"153\" class=\"code-line\">ESLint reports errors like:</p>\n<div class=\"code-block-container\"><pre class=\"shiki github-dark\" style=\"background-color:#151e2c;color:#e1e4e8\"><code class=\"code-line\" data-line=\"155\"><span class=\"line\"><span>error  Attribute 'button' expects boolean type, use property binding [button]=\"true\"  @rdlabo/rules/ionic-attr-type-check</span></span>\n<span class=\"line\"><span>error  Attribute 'lines' expects string literal type, use valid value like \"full\", \"inset\", or \"none\"  @rdlabo/rules/ionic-attr-type-check</span></span>\n<span class=\"line\"><span>error  Attribute 'value' expects number type, use property binding [value]=\"50\"  @rdlabo/rules/ionic-attr-type-check</span></span>\n<span class=\"line\"><span></span></span></code></pre></div><p data-line=\"161\" class=\"code-line\">With the <code>--fix</code> option, it automatically corrects to:</p>\n<div class=\"code-block-container\"><pre class=\"shiki github-dark\" style=\"background-color:#151e2c;color:#e1e4e8\"><code class=\"code-line\" data-line=\"163\"><span class=\"line\"><span style=\"color:#E1E4E8\">&lt;</span><span style=\"color:#85E89D\">ion-item</span><span style=\"color:#B392F0\"> [button]</span><span style=\"color:#E1E4E8\">=</span><span style=\"color:#9ECBFF\">\"true\"</span><span style=\"color:#B392F0\"> lines</span><span style=\"color:#E1E4E8\">=</span><span style=\"color:#9ECBFF\">\"full\"</span><span style=\"color:#E1E4E8\">&gt;</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  &lt;</span><span style=\"color:#85E89D\">ion-label</span><span style=\"color:#E1E4E8\">&gt;Settings&lt;/</span><span style=\"color:#85E89D\">ion-label</span><span style=\"color:#E1E4E8\">&gt;</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">&lt;/</span><span style=\"color:#85E89D\">ion-item</span><span style=\"color:#E1E4E8\">&gt;</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">&lt;</span><span style=\"color:#85E89D\">ion-progress-bar</span><span style=\"color:#B392F0\"> [value]</span><span style=\"color:#E1E4E8\">=</span><span style=\"color:#9ECBFF\">\"50\"</span><span style=\"color:#E1E4E8\">&gt;&lt;/</span><span style=\"color:#85E89D\">ion-progress-bar</span><span style=\"color:#E1E4E8\">&gt;</span></span>\n<span class=\"line\"></span></code></pre></div><h2 id=\"implementation-highlights\" data-line=\"170\" class=\"code-line\"><a class=\"header-anchor-link\" href=\"#implementation-highlights\" aria-hidden=\"true\"></a> Implementation highlights</h2>\n<h2 id=\"how-dynamic-type-parsing-works\" data-line=\"172\" class=\"code-line\"><a class=\"header-anchor-link\" href=\"#how-dynamic-type-parsing-works\" aria-hidden=\"true\"></a> How dynamic type parsing works</h2>\n<p data-line=\"174\" class=\"code-line\">The rule follows these steps:</p>\n<ol data-line=\"176\" class=\"code-line\">\n<li data-line=\"176\" class=\"code-line\">Load the type definition file: parse <code>@ionic/core/dist/types/components.d.ts</code></li>\n<li data-line=\"177\" class=\"code-line\">Extract component info: get each component's attributes and their types</li>\n<li data-line=\"178\" class=\"code-line\">Parse templates: find Ionic components in HTML templates</li>\n<li data-line=\"179\" class=\"code-line\">Run type checks: compare attribute values to expected types</li>\n<li data-line=\"180\" class=\"code-line\">Generate fix suggestions: propose property bindings or valid values</li>\n</ol>\n<h2 id=\"performance-optimizations\" data-line=\"182\" class=\"code-line\"><a class=\"header-anchor-link\" href=\"#performance-optimizations\" aria-hidden=\"true\"></a> Performance optimizations</h2>\n<ul data-line=\"184\" class=\"code-line\">\n<li data-line=\"184\" class=\"code-line\">Caching: type info is cached on first load for better performance</li>\n<li data-line=\"185\" class=\"code-line\">Parse only when needed: type checks run only when Ionic components are detected</li>\n<li data-line=\"186\" class=\"code-line\">Efficient string handling: fast template parsing with regular expressions</li>\n</ul>\n<h2 id=\"effects-in-real-projects\" data-line=\"188\" class=\"code-line\"><a class=\"header-anchor-link\" href=\"#effects-in-real-projects\" aria-hidden=\"true\"></a> Effects in real projects</h2>\n<p data-line=\"190\" class=\"code-line\">Projects that adopted this rule have seen:</p>\n<h2 id=\"faster-development\" data-line=\"192\" class=\"code-line\"><a class=\"header-anchor-link\" href=\"#faster-development\" aria-hidden=\"true\"></a> Faster development</h2>\n<ul data-line=\"193\" class=\"code-line\">\n<li data-line=\"193\" class=\"code-line\">Shorter code reviews: catching type-related issues upfront reduces review comments</li>\n<li data-line=\"194\" class=\"code-line\">Less debugging: preventing runtime errors saves significant debugging time</li>\n</ul>\n<h2 id=\"better-code-quality\" data-line=\"196\" class=\"code-line\"><a class=\"header-anchor-link\" href=\"#better-code-quality\" aria-hidden=\"true\"></a> Better code quality</h2>\n<ul data-line=\"197\" class=\"code-line\">\n<li data-line=\"197\" class=\"code-line\">Consistent style: unified property binding usage across the team</li>\n<li data-line=\"198\" class=\"code-line\">Stronger TypeScript safety: fewer compile-time errors</li>\n</ul>\n<h2 id=\"lower-learning-curve\" data-line=\"200\" class=\"code-line\"><a class=\"header-anchor-link\" href=\"#lower-learning-curve\" aria-hidden=\"true\"></a> Lower learning curve</h2>\n<ul data-line=\"201\" class=\"code-line\">\n<li data-line=\"201\" class=\"code-line\">Onboarding: newcomers learn correct Ionic usage through ESLint errors</li>\n<li data-line=\"202\" class=\"code-line\">Less doc hunting: error messages show the correct type for each attribute</li>\n</ul>\n<h2 id=\"summary\" data-line=\"204\" class=\"code-line\"><a class=\"header-anchor-link\" href=\"#summary\" aria-hidden=\"true\"></a> Summary</h2>\n<p data-line=\"206\" class=\"code-line\">Attribute type mismatches were a frequent pain in Ionic Angular development. The <code>@rdlabo/rules/ionic-attr-type-check</code> rule I built provides:</p>\n<ol data-line=\"208\" class=\"code-line\">\n<li data-line=\"208\" class=\"code-line\">Automatic detection: validates boolean, number, and string literal union attributes on Ionic components</li>\n<li data-line=\"209\" class=\"code-line\">Auto-fix: bulk fixes with ESLint's <code>--fix</code> option</li>\n<li data-line=\"210\" class=\"code-line\">Dynamic behavior: reads attribute info from the type definition file at runtime</li>\n<li data-line=\"211\" class=\"code-line\">Future-proofing: adapts automatically to new Ionic versions</li>\n</ol>\n<p data-line=\"213\" class=\"code-line\">Developers can build Ionic Angular apps more safely and efficiently.</p>\n<p data-line=\"215\" class=\"code-line\">If your team uses Ionic Angular, consider adopting it—you should see better code quality and smoother development.</p>\n<p data-line=\"217\" class=\"code-line\">For details and the latest updates, see the <a href=\"https://github.com/rdlabo-dev/eslint-plugin-rules\" target=\"_blank\" rel=\"noopener noreferrer\">GitHub repository</a>.</p>\n","headings":[{"id":"html-vs.-js-frameworks","text":"HTML vs. JS frameworks","level":2},{"id":"one-shot-fix-with-an-eslint-rule","text":"One-shot fix with an ESLint rule","level":2},{"id":"main-features","text":"Main features","level":2},{"id":"1.-automatic-type-detection","text":"1. Automatic type detection","level":3},{"id":"2.-validation-and-fix-support","text":"2. Validation and fix support","level":3},{"id":"3.-auto-fix","text":"3. Auto-fix","level":3},{"id":"usage","text":"Usage","level":2},{"id":"installation","text":"Installation","level":2},{"id":"configuration","text":"Configuration","level":2},{"id":"example-in-practice","text":"Example in practice","level":2},{"id":"implementation-highlights","text":"Implementation highlights","level":2},{"id":"how-dynamic-type-parsing-works","text":"How dynamic type parsing works","level":2},{"id":"performance-optimizations","text":"Performance optimizations","level":2},{"id":"effects-in-real-projects","text":"Effects in real projects","level":2},{"id":"faster-development","text":"Faster development","level":2},{"id":"better-code-quality","text":"Better code quality","level":2},{"id":"lower-learning-curve","text":"Lower learning curve","level":2},{"id":"summary","text":"Summary","level":2}]} as const;
